from collections import deque

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        # If already equal
        if x == y:
            return 0

        # If x is smaller, only increments are useful
        if x < y:
            return y - x

        # BFS from x to y
        max_val = max(x, y) + 20  # safe upper bound
        visited = set()
        q = deque()
        q.append((x, 0))
        visited.add(x)

        while q:
            val, dist = q.popleft()

            # Generate possible next states
            # Decrement
            if val - 1 >= 0 and (val - 1) not in visited:
                if val - 1 == y:
                    return dist + 1
                visited.add(val - 1)
                q.append((val - 1, dist + 1))

            # Increment
            if val + 1 <= max_val and (val + 1) not in visited:
                if val + 1 == y:
                    return dist + 1
                visited.add(val + 1)
                q.append((val + 1, dist + 1))

            # Divide by 5
            if val % 5 == 0:
                new_val = val // 5
                if new_val not in visited:
                    if new_val == y:
                        return dist + 1
                    visited.add(new_val)
                    q.append((new_val, dist + 1))

            # Divide by 11
            if val % 11 == 0:
                new_val = val // 11
                if new_val not in visited:
                    if new_val == y:
                        return dist + 1
                    visited.add(new_val)
                    q.append((new_val, dist + 1))

        # In theory, BFS should always find a path
        return -1

