from typing import List
import bisect

class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        n = len(s)
        la = len(a)
        lb = len(b)

        # Find all start indices of substring a
        list_a = []
        for i in range(n - la + 1):
            if s[i:i+la] == a:
                list_a.append(i)

        # Find all start indices of substring b
        list_b = []
        for j in range(n - lb + 1):
            if s[j:j+lb] == b:
                list_b.append(j)

        if not list_b:
            return []

        result = []
        # For each i in list_a, check nearest j in list_b
        for i in list_a:
            # Find the first j >= i - k
            idx = bisect.bisect_left(list_b, i - k)
            found = False
            # Check idx
            if idx < len(list_b):
                if abs(list_b[idx] - i) <= k:
                    found = True
            # Check idx - 1
            if not found and idx > 0:
                if abs(list_b[idx-1] - i) <= k:
                    found = True
            if found:
                result.append(i)

        return result

