class Solution:
    def canSortArray(self, nums):
        # Helper to count set bits
        def popcount(x):
            return bin(x).count('1')

        # Original popcount sequence
        orig_pops = [popcount(x) for x in nums]
        # Popcount sequence after sorting nums
        sorted_nums = sorted(nums)
        sorted_pops = [popcount(x) for x in sorted_nums]

        return orig_pops == sorted_pops

