from typing import List
from collections import Counter

class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        cnt = Counter(nums)
        max_val = max(nums)
        ans = 0

        # Handle base 1 separately: all values are 1
        if 1 in cnt:
            c = cnt[1]
            if c % 2 == 0:
                c -= 1
            ans = max(ans, c)

        # Process bases greater than 1
        for base in cnt:
            if base == 1:
                continue
            if cnt[base] == 0:
                continue

            # Generate powers: base^(2^i)
            powers = []
            cur = base
            while cur <= max_val:
                powers.append(cur)
                # Prevent overflow and stop if next power exceeds max_val
                if cur > max_val // cur:
                    break
                cur = cur * cur

            # Iterate over possible maximum exponent index m
            for m in range(len(powers)):
                # Check counts for all exponents < m (need 2 copies each)
                ok = True
                for i in range(m):
                    if cnt.get(powers[i], 0) < 2:
                        ok = False
                        break
                if not ok:
                    break  # further m will also fail

                # Check count for exponent m (need at least 1 copy)
                if cnt.get(powers[m], 0) < 1:
                    break

                # Valid pattern length
                length = 2 * m + 1
                ans = max(ans, length)

        return ans

from typing import List

class Solution:
    def maxPalindromesAfterOperations(self, words: List[str]) -> int:
        # Count total occurrences of each character
        char_counts = [0] * 26
        for w in words:
            for ch in w:
                char_counts[ord(ch) - 97] += 1

        # Total pairs available from all characters
        pairs_available = sum(c // 2 for c in char_counts)

        # For each string, compute pairs needed (floor(len/2))
        pair_needs = [len(w) // 2 for w in words]
        pair_needs.sort()

        count = 0
        used_pairs = 0
        for need in pair_needs:
            if used_pairs + need <= pairs_available:
                used_pairs += need
                count += 1
            else:
                break

        return count

from typing import List

class Solution:
    def longestCommonPrefix(self, arr1: List[int], arr2: List[int]) -> int:
        # Build a trie for prefixes of numbers in arr2
        children = [{}]  # root node at index 0

        for num in arr2:
            node = 0
            for ch in str(num):
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                node = nxt

        # Find maximum common prefix length with numbers in arr1
        max_len = 0
        for num in arr1:
            node = 0
            depth = 0
            for ch in str(num):
                if ch in children[node]:
                    node = children[node][ch]
                    depth += 1
                    if depth > max_len:
                        max_len = depth
                else:
                    break

        return max_len

