    H, W, K = map(int, input().split())
    grid = [input().strip() for _ in range(H)]

    INF = 10**9
    ans = INF

    # Horizontal segments
    if K <= W:
        for i in range(H):
            pref_dot = [0] * (W + 1)
            pref_x = [0] * (W + 1)
            row = grid[i]
            for j in range(W):
                pref_dot[j + 1] = pref_dot[j] + (row[j] == '.')
                pref_x[j + 1] = pref_x[j] + (row[j] == 'x')
            for start in range(0, W - K + 1):
                dot_cnt = pref_dot[start + K] - pref_dot[start]
                x_cnt = pref_x[start + K] - pref_x[start]
                if x_cnt == 0:
                    ans = min(ans, dot_cnt)

    # Vertical segments
    if K <= H:
        for j in range(W):
            pref_dot = [0] * (H + 1)
            pref_x = [0] * (H + 1)
            for i in range(H):
                pref_dot[i + 1] = pref_dot[i] + (grid[i][j] == '.')
                pref_x[i + 1] = pref_x[i] + (grid[i][j] == 'x')
