import sys

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    N = int(next(it))
    Q = [int(next(it)) for _ in range(N)]
    A = [int(next(it)) for _ in range(N)]
    B = [int(next(it)) for _ in range(N)]

    # helper for ceil division a / b (b may be negative)
    def ceil_div(a: int, b: int) -> int:
        return -((-a) // b)

    # feasibility test for given total servings S
    def feasible(S: int) -> bool:
        low, high = 0, S
        for i in range(N):
            diff = A[i] - B[i]
            rhs = Q[i] - B[i] * S
            if diff == 0:
                if rhs < 0:
                    return False
                continue
            if diff > 0:
                # x <= rhs // diff
                if rhs < 0:
                    return False
                high = min(high, rhs // diff)
            else:  # diff < 0
                # x >= ceil(rhs / diff)
                low = max(low, ceil_div(rhs, diff))
            if low > high:
                return False
        return True

    # upper bound for binary search
    upper = 0
    INF = 10**9
    for i in range(N):
        min_pos = INF
        if A[i] > 0:
            min_pos = min(min_pos, A[i])
        if B[i] > 0:
            min_pos = min(min_pos, B[i])
        if min_pos != INF:
            upper += Q[i] // min_pos
    # binary search for maximum S
    lo, hi = 0, upper + 1
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

if __name__ == "__main__":
    solve()

