import sys

def solve() -> None:
    sys.setrecursionlimit(1 << 20)
    N = int(sys.stdin.readline())

    memo = {1: 0}

    def f(n: int) -> int:
        """Return total cost starting from a single number n."""
        if n in memo:
            return memo[n]
        a = n // 2          # floor(n/2)
        b = (n + 1) // 2    # ceil(n/2)
        memo[n] = n + f(a) + f(b)
        return memo[n]

    print(f(N))

if __name__ == "__main__":
    solve()

import sys

def solve() -> None:
    H, W, N = map(int, sys.stdin.readline().split())
    T = sys.stdin.readline().strip()
    land = []
    for _ in range(H):
        s = sys.stdin.readline().strip()
        bits = 0
        for j, ch in enumerate(s):
            if ch == '.':
                bits |= 1 << j
        land.append(bits)

    reach = land[:]          # possible starting positions

    for move in T:
        nreach = [0] * H
        if move == 'L':
            for i in range(H):
                nreach[i] = (reach[i] >> 1) & land[i]
        elif move == 'R':
            for i in range(H):
                nreach[i] = (reach[i] << 1) & land[i]
        elif move == 'U':
            for i in range(1, H):
                nreach[i-1] |= (reach[i] & land[i-1])
        elif move == 'D':
            for i in range(H-1):
                nreach[i+1] |= (reach[i] & land[i+1])
        reach = nreach

    # count set bits
    ans = sum(r.bit_count() for r in reach)
    print(ans)

if __name__ == "__main__":
    solve()

import sys
import math

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N, M, K = map(int, data)

    # greatest common divisor and least common multiple
    g = math.gcd(N, M)
    lcm = N // g * M  # avoid overflow (Python int handles large numbers anyway)

    def count(x: int) -> int:
        """Number of positive integers <= x divisible by exactly one of N and M."""
        return x // N + x // M - 2 * (x // lcm)

    # binary search for smallest x with count(x) >= K
    low, high = 1, K * max(N, M)  # upper bound is safe
    while low < high:
        mid = (low + high) // 2
        if count(mid) >= K:
            high = mid
        else:
            low = mid + 1

    print(low)

if __name__ == "__main__":
    solve()

