import sys
from collections import defaultdict

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]

    MAXV = 200000
    spf = list(range(MAXV + 1))
    for i in range(2, int(MAXV ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, MAXV + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def square_free(x: int) -> int:
        res = 1
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt ^= 1  # only need parity
            if cnt:
                res *= p
        return res

    zero_count = 0
    freq = defaultdict(int)
    for v in A:
        if v == 0:
            zero_count += 1
        else:
            freq[square_free(v)] += 1

    ans = 0
    # pairs among non-zero with same square-free part
    for k in freq.values():
        ans += k * (k - 1) // 2

    # pairs involving zeros
    ans += zero_count * (zero_count - 1) // 2      # zero-zero pairs
    ans += zero_count * (N - zero_count)          # zero with non-zero

    print(ans)

if __name__ == "__main__":
    solve()

