def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        N = int(next(it))
    except StopIteration:
        return
    A = int(next(it))
    B = int(next(it))
    Ds = [int(next(it)) for _ in range(N)]

    m = A + B
    # allowed intervals on [0, m-1], inclusive
    allowed = [[0, m - 1]]

    for D in Ds:
        d_mod = D % m
        l = (m - d_mod) % m
        r = (l + A - 1) % m
        # build S intervals
        if l <= r:
            S = [[l, r]]
        else:
            S = [[l, m - 1], [0, r]]

        new_allowed = []
        for a1, b1 in allowed:
            for a2, b2 in S:
                lo = max(a1, a2)
                hi = min(b1, b2)
                if lo <= hi:
                    new_allowed.append([lo, hi])
        allowed = new_allowed
        if not allowed:
            print("No")
            return

    print("Yes")

