from typing import List, Dict, Set

class Solution:
    def shortestSubstrings(self, arr: List[str]) -> List[str]:
        n = len(arr)
        # Map each substring to the set of indices of strings containing it
        sub_to_indices: Dict[str, Set[int]] = {}
        # Store all substrings for each string to avoid recomputing
        substrings_per_string: List[List[str]] = []

        for idx, s in enumerate(arr):
            subs = set()  # use set to avoid duplicate substrings from same string
            L = len(s)
            for i in range(L):
                for j in range(i + 1, L + 1):
                    sub = s[i:j]
                    subs.add(sub)
            substrings_per_string.append(list(subs))
            for sub in subs:
                if sub not in sub_to_indices:
                    sub_to_indices[sub] = set()
                sub_to_indices[sub].add(idx)

        answer = [''] * n
        for idx, subs in enumerate(substrings_per_string):
            best_sub = None
            best_len = None
            for sub in subs:
                indices = sub_to_indices[sub]
                if len(indices) == 1 and idx in indices:
                    l = len(sub)
                    if best_sub is None or l < best_len or (l == best_len and sub < best_sub):
                        best_sub = sub
                        best_len = l
            if best_sub is not None:
                answer[idx] = best_sub
            else:
                answer[idx] = ''
        return answer

