class Solution:
    def minimumDeletions(self, word: str, k: int) -> int:
        # Count frequencies of each lowercase letter
        freq = [0] * 26
        for ch in word:
            freq[ord(ch) - 97] += 1

        total_len = len(word)
        max_f = max(freq)
        if max_f == 0:
            return 0  # empty string edge case

        best_kept = 0
        # Iterate over possible lower bound L of kept frequencies
        for L in range(1, max_f + 1):
            R = L + k
            kept = 0
            for f in freq:
                if f >= L:
                    kept += f if f <= R else R
            if kept > best_kept:
                best_kept = kept

        return total_len - best_kept

