import heapq
from typing import List

class Solution:
    def mostFrequentIDs(self, nums: List[int], freq: List[int]) -> List[int]:
        counts = {}                     # current count per ID
        max_heap = []                   # heap of (-count, id)
        ans = []

        for id_val, delta in zip(nums, freq):
            if delta > 0:
                # add IDs
                new_count = counts.get(id_val, 0) + delta
                counts[id_val] = new_count
                heapq.heappush(max_heap, (-new_count, id_val))
            else:
                # remove IDs
                # delta is negative
                current = counts.get(id_val, 0)
                new_count = current + delta  # delta < 0
                if new_count == 0:
                    counts.pop(id_val, None)
                else:
                    counts[id_val] = new_count
                    heapq.heappush(max_heap, (-new_count, id_val))

            # determine current maximum frequency
            if not counts:
                ans.append(0)
            else:
                # clean up stale heap entries
                while max_heap:
                    cnt_neg, cur_id = max_heap[0]
                    cnt = -cnt_neg
                    if cur_id in counts and counts[cur_id] == cnt:
                        ans.append(cnt)
                        break
                    heapq.heappop(max_heap)
                else:
                    # heap exhausted, no valid entries
                    ans.append(0)

        return ans

class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        # Helper to compute cyclic distance between two lowercase letters
        def dist(a: str, b: str) -> int:
            diff = abs(ord(a) - ord(b))
            return min(diff, 26 - diff)

        res = []
        for ch in s:
            # Try each letter from 'a' to 'z' in order
            for c in map(chr, range(ord('a'), ord('z') + 1)):
                d = dist(ch, c)
                if d <= k:
                    res.append(c)
                    k -= d
                    break
        return ''.join(res)

