class Solution:
    def minimizeStringValue(self, s: str) -> str:
        """
        Replace '?' in s with lowercase letters to minimize the total
        number of repeated character pairs. Among all minimal-cost
        strings, return the lexicographically smallest one.
        """
        n = len(s)
        # Count occurrences of each letter in the current string
        counts = [0] * 26
        for ch in s:
            if ch != '?':
                counts[ord(ch) - ord('a')] += 1

        s_list = list(s)
        for i, ch in enumerate(s_list):
            if ch == '?':
                # Find the letter with minimal current count
                # In case of tie, pick lexicographically smallest
                min_count = counts[0]
                min_letter = 0
                for l in range(1, 26):
                    c = counts[l]
                    if c < min_count:
                        min_count = c
                        min_letter = l
                # Assign the chosen letter
                s_list[i] = chr(ord('a') + min_letter)
                counts[min_letter] += 1

        return ''.join(s_list)

from typing import List

class Solution:
    def numberOfRightTriangles(self, grid: List[List[int]]) -> int:
        if not grid or not grid[0]:
            return 0

        m, n = len(grid), len(grid[0])

        # Count ones in each row and column
        row_counts = [0] * m
        col_counts = [0] * n

        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    row_counts[i] += 1
                    col_counts[j] += 1

        total_triangles = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    # Number of other 1's in the same row (excluding this cell)
                    row_neighbors = row_counts[i] - 1
                    # Number of other 1's in the same column (excluding this cell)
                    col_neighbors = col_counts[j] - 1
                    total_triangles += row_neighbors * col_neighbors

        return total_triangles

