class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7
        # dp[z][o][last][len] = number of ways
        # last: 0 for zero, 1 for one
        # len: current run length of the last bit (1..limit)
        dp = [[[[0]*(limit+1) for _ in range(2)] for _ in range(one+1)] for _ in range(zero+1)]

        # initial placements
        if zero > 0:
            dp[1][0][0][1] = 1
        if one > 0:
            dp[0][1][1][1] = 1

        for z_used in range(zero+1):
            for o_used in range(one+1):
                for last in (0, 1):
                    for run_len in range(1, limit+1):
                        val = dp[z_used][o_used][last][run_len]
                        if not val:
                            continue
                        # try to add a zero
                        if last == 0:
                            if z_used + 1 <= zero and run_len + 1 <= limit:
                                dp[z_used+1][o_used][0][run_len+1] = (dp[z_used+1][o_used][0][run_len+1] + val) % MOD
                        else:  # last == 1
                            if z_used + 1 <= zero:
                                dp[z_used+1][o_used][0][1] = (dp[z_used+1][o_used][0][1] + val) % MOD
                        # try to add a one
                        if last == 1:
                            if o_used + 1 <= one and run_len + 1 <= limit:
                                dp[z_used][o_used+1][1][run_len+1] = (dp[z_used][o_used+1][1][run_len+1] + val) % MOD
                        else:  # last == 0
                            if o_used + 1 <= one:
                                dp[z_used][o_used+1][1][1] = (dp[z_used][o_used+1][1][1] + val) % MOD

        result = 0
        for last in (0, 1):
            for run_len in range(1, limit+1):
                result = (result + dp[zero][one][last][run_len]) % MOD
        return result

