from typing import List

class Solution:
    def maximumEnergy(self, energy: List[int], k: int) -> int:
        n = len(energy)
        dp = [0] * n
        # Compute sums from the end towards the start
        for i in range(n - 1, -1, -1):
            nxt = i + k
            if nxt < n:
                dp[i] = energy[i] + dp[nxt]
            else:
                dp[i] = energy[i]
        # The answer is the maximum sum among all starting positions
        return max(dp)

