from typing import List

class Solution:
    def sumDigitDifferences(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 2:
            return 0

        # Determine number of digits (all numbers have same length)
        m = len(str(nums[0]))

        # Precompute powers of 10 for digit extraction
        pow10 = [1] * m
        for i in range(1, m):
            pow10[i] = pow10[i - 1] * 10

        # Frequency of digits at each position
        freq = [[0] * 10 for _ in range(m)]

        for num in nums:
            for pos in range(m):
                digit = (num // pow10[pos]) % 10
                freq[pos][digit] += 1

        total_pairs = n * (n - 1) // 2
        same_pairs_total = 0
        for pos in range(m):
            same_pairs_pos = 0
            for d in range(10):
                cnt = freq[pos][d]
                if cnt > 1:
                    same_pairs_pos += cnt * (cnt - 1) // 2
            same_pairs_total += same_pairs_pos

        # Sum of differing pairs across all positions
        result = m * total_pairs - same_pairs_total
        return result

class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        # Prefix sums of character counts
        pref = [[0] * 26 for _ in range(n + 1)]
        for i, ch in enumerate(s, 1):
            for c in range(26):
                pref[i][c] = pref[i - 1][c]
            pref[i][ord(ch) - 97] += 1

        INF = n + 1
        dp = [INF] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(0, i):
                # compute frequencies for substring s[j:i]
                freq = [pref[i][c] - pref[j][c] for c in range(26)]
                distinct = 0
                k = None
                balanced = True
                for f in freq:
                    if f:
                        distinct += 1
                        if k is None:
                            k = f
                        elif f != k:
                            balanced = False
                            break
                if balanced:
                    dp[i] = min(dp[i], dp[j] + 1)
        return dp[n]

