class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        # Prefix sums of character counts
        pref = [[0] * 26 for _ in range(n + 1)]
        for i, ch in enumerate(s, 1):
            for c in range(26):
                pref[i][c] = pref[i - 1][c]
            pref[i][ord(ch) - 97] += 1

        INF = n + 1
        dp = [INF] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(0, i):
                # compute frequencies for substring s[j:i]
                freq = [pref[i][c] - pref[j][c] for c in range(26)]
                distinct = 0
                k = None
                balanced = True
                for f in freq:
                    if f:
                        distinct += 1
                        if k is None:
                            k = f
                        elif f != k:
                            balanced = False
                            break
                if balanced:
                    dp[i] = min(dp[i], dp[j] + 1)
        return dp[n]
