def solve() -> None:
    N = int(sys.stdin.readline().strip())
    cumulative = 0
    L = 1

    while True:
        if L == 1:
            count = 10
        elif L % 2 == 0:
            k = L // 2
            count = 9 * pow(10, k - 1)
        else:
            k = L // 2
            count = 9 * pow(10, k)

        if cumulative + count >= N:
            break

        cumulative += count
        L += 1

    offset = N - cumulative - 1  # 0‑based index within this length group

    if L == 1:
        result = str(offset)
    elif L % 2 == 0:
        k = L // 2
        first_half = pow(10, k - 1) + offset
        result = str(first_half) + str(first_half)[::-1]
    else:
        k = L // 2
        prefix = pow(10, k) + offset
        s = str(prefix)
        result = s + s[:-1][::-1]

    print(result)

if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def minimumArea(self, grid: List[List[int]]) -> int:
        """
        Find the smallest axis-aligned rectangle that covers all 1's in the grid.
        The rectangle's sides are parallel to the grid axes.
        Return the area of that rectangle.
        """
        rows = len(grid)
        cols = len(grid[0]) if rows else 0

        # Initialize bounds to extreme values
        min_row, max_row = rows, -1
        min_col, max_col = cols, -1

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 1:
                    if r < min_row:
                        min_row = r
                    if r > max_row:
                        max_row = r
                    if c < min_col:
                        min_col = c
                    if c > max_col:
                        max_col = c

        # Since the problem guarantees at least one 1, bounds are valid
        height = max_row - min_row + 1
        width = max_col - min_col + 1
        return height * width

