from typing import List

class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        # Count parity of each number
        even_count = 0
        odd_count = 0
        parities = []
        for x in nums:
            p = x & 1
            parities.append(p)
            if p == 0:
                even_count += 1
            else:
                odd_count += 1

        # Longest alternating subsequence using greedy
        def longest_alternating(start_parity: int) -> int:
            cur = start_parity
            length = 0
            for p in parities:
                if p == cur:
                    length += 1
                    cur ^= 1  # toggle expected parity
            return length

        alt_len = max(longest_alternating(0), longest_alternating(1))

        return max(even_count, odd_count, alt_len)

