class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # adjacency list: each node i has a forward edge to i+1 initially
        adj: List[List[int]] = [[] for _ in range(n)]
        for i in range(n - 1):
            adj[i].append(i + 1)

        ans: List[int] = []
        INF = 10 ** 9

        for u, v in queries:
            # add the new edge
            adj[u].append(v)

            # compute shortest distances from 0 using DP in topological order
            dist = [INF] * n
            dist[0] = 0
            for i in range(n):
                di = dist[i]
                if di == INF:
                    continue
                for j in adj[i]:
                    if di + 1 < dist[j]:
                        dist[j] = di + 1

            ans.append(dist[n - 1])

        return ans

