from collections import deque
from typing import List

class Solution:
    def findWinningPlayer(self, skills: List[int], k: int) -> int:
        n = len(skills)
        # If k is large enough, the maximum skill player will eventually win
        if k >= n - 1:
            max_skill = max(skills)
            return skills.index(max_skill)

        dq = deque(range(n))          # queue of player indices
        prev_winner = dq[0]           # initial front player
        win_streak = 0

        while True:
            # Take the first two players
            first = dq.popleft()
            second = dq.popleft()

            # Determine winner and loser
            if skills[first] > skills[second]:
                winner, loser = first, second
            else:
                winner, loser = second, first

            # Append loser to the back
            dq.append(loser)
            # Put winner back to the front
            dq.appendleft(winner)

            # Update win streak
            if winner == prev_winner:
                win_streak += 1
            else:
                win_streak = 1
                prev_winner = winner

            if win_streak == k:
                return winner

from typing import List

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # Compress values to small indices
        uniq = sorted(set(nums))
        val_to_idx = {v: i for i, v in enumerate(uniq)}
        m = len(uniq)

        max_blocks = k + 1  # maximum number of blocks allowed

        # dp[b][v] = maximum length of subsequence with b blocks ending with value v
        # initialize with -inf (represented by -1 for impossible)
        dp = [[-1] * m for _ in range(max_blocks + 1)]

        best = 0

        for num in nums:
            x = val_to_idx[num]
            # copy current dp to newdp to allow skipping current element
            newdp = [row[:] for row in dp]

            # Start a new block with this element (only if we haven't started any block yet)
            if newdp[1][x] < 1:
                newdp[1][x] = 1
                best = max(best, 1)

            # Transition from existing states
            for b in range(1, max_blocks + 1):
                for v in range(m):
                    cur_len = dp[b][v]
                    if cur_len == -1:
                        continue
                    # Option 1: extend current block if same value
                    if v == x:
                        if newdp[b][x] < cur_len + 1:
                            newdp[b][x] = cur_len + 1
                            best = max(best, cur_len + 1)
                    # Option 2: start a new block if we have room
                    elif b < max_blocks:
                        if newdp[b + 1][x] < cur_len + 1:
                            newdp[b + 1][x] = cur_len + 1
                            best = max(best, cur_len + 1)

            dp = newdp

        return best

from typing import List

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        if not grid:
            return 0
        m, n = len(grid), len(grid[0])

        # Cost to make all rows palindromic
        row_cost = 0
        for r in range(m):
            row = grid[r]
            for i in range(n // 2):
                if row[i] != row[n - 1 - i]:
                    row_cost += 1

        # Cost to make all columns palindromic
        col_cost = 0
        for c in range(n):
            for i in range(m // 2):
                if grid[i][c] != grid[m - 1 - i][c]:
                    col_cost += 1

        return min(row_cost, col_cost)

