            if sum_so_far % K == 0:
                out_lines.append(' '.join(map(str, cur)))
            return
        for v in range(1, R[pos] + 1):
            cur[pos] = v
            dfs(pos + 1, sum_so_far + v)

    dfs(0, 0)

    sys.stdout.write('\n'.join(out_lines))

