    dp1 = NEG     # parity 1: odd number of defeated monsters so far

    for a in A:
        # copy current dp values
        cur0, cur1 = dp0, dp1

        # skip current monster
        # dp0, dp1 remain unchanged

        # defeat current monster
        # from parity 0 -> new parity 1, no bonus
        if cur0 != NEG:
            gain = a  # no bonus
            if cur0 + gain > dp1:
                dp1 = cur0 + gain

        # from parity 1 -> new parity 0, bonus a
        if cur1 != NEG:
            gain = a * 2  # a + bonus a
            if cur1 + gain > dp0:
                dp0 = cur1 + gain

    print(max(dp0, dp1))

