import sys

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        P = [int(next(it)) for _ in range(n)]

        # check if already sorted
        sorted_flag = True
        for i, val in enumerate(P, start=1):
            if val != i:
                sorted_flag = False
                break
        if sorted_flag:
            out_lines.append('0')
            continue

        # prefix max
        pre_max = [0] * (n + 1)
        for i in range(1, n + 1):
            pre_max[i] = pre_max[i - 1]
            if P[i - 1] > pre_max[i]:
                pre_max[i] = P[i - 1]

        # suffix min
        suf_min = [n + 1] * (n + 2)
        for i in range(n, 0, -1):
            suf_min[i] = suf_min[i + 1]
            if P[i - 1] < suf_min[i]:
                suf_min[i] = P[i - 1]

        # search for k giving answer 1
        found_one = False
        for k in range(1, n + 1):
            if P[k - 1] != k:
                continue
            if pre_max[k - 1] <= k - 1 and suf_min[k + 1] >= k + 1:
                found_one = True
                break

        out_lines.append('1' if found_one else '2')

    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        # Precompute for each number all values reachable by at most one swap
        reachable = {}
        for num in nums:
            s = str(num)
            vals = {num}  # include original
            L = len(s)
            # generate all swaps
            for i in range(L):
                for j in range(i + 1, L):
                    if s[i] == s[j]:
                        continue  # swapping identical digits yields same number, already in set
                    lst = list(s)
                    lst[i], lst[j] = lst[j], lst[i]
                    new_val = int(''.join(lst))  # int conversion discards leading zeros
                    vals.add(new_val)
            reachable[num] = vals

        n = len(nums)
        count = 0
        for i in range(n):
            a = nums[i]
            for j in range(i + 1, n):
                b = nums[j]
                # Check if one can transform into the other
                if b in reachable[a] or a in reachable[b]:
                    count += 1
        return count

