from typing import List
import heapq

class Solution:
    def resultsArray(self, queries: List[List[int]], k: int) -> List[int]:
        """
        Maintains the k smallest Manhattan distances seen so far using a max-heap.
        For each new query, updates the heap and records the current k-th smallest distance.
        """
        # max-heap implemented by storing negative distances
        max_heap: List[int] = []
        results: List[int] = []

        for x, y in queries:
            d = abs(x) + abs(y)

            if len(max_heap) < k:
                heapq.heappush(max_heap, -d)
            else:
                # top of max-heap is the largest among the k smallest distances
                if -max_heap[0] > d:
                    heapq.heappop(max_heap)
                    heapq.heappush(max_heap, -d)

            if len(max_heap) < k:
                results.append(-1)
            else:
                results.append(-max_heap[0])

        return results

