import sys
import threading
from typing import List

class Solution:
    class Line:
        __slots__ = ("m", "b")
        def __init__(self, m: int, b: int):
            self.m = m
            self.b = b
        def eval(self, x: int) -> int:
            return self.m * x + self.b

    class Node:
        __slots__ = ("line", "left", "right")
        def __init__(self, line=None):
            self.line = line
            self.left = None
            self.right = None

    def __init__(self):
        self.root = None

    def insert(self, node, l, r, new_line):
        if node.line is None:
            node.line = new_line
            return
        mid = (l + r) >> 1
        left_is_better = new_line.eval(l) > node.line.eval(l)
        mid_is_better = new_line.eval(mid) > node.line.eval(mid)

        if mid_is_better:
            node.line, new_line = new_line, node.line

        if l == r:
            return

        if left_is_better != mid_is_better:
            if node.left is None:
                node.left = self.Node()
            self.insert(node.left, l, mid, new_line)
        else:
            if node.right is None:
                node.right = self.Node()
            self.insert(node.right, mid + 1, r, new_line)

    def query(self, node, l, r, x):
        if node is None or node.line is None:
            return -10**30
        res = node.line.eval(x)
        if l == r:
            return res
        mid = (l + r) >> 1
        if x <= mid:
            return max(res, self.query(node.left, l, mid, x))
        else:
            return max(res, self.query(node.right, mid + 1, r, x))

