class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        # Build trie of all prefixes
        trie = {}
        # Each node will be a dict: {'$': child_dict} or just child dict
        # We'll store children in a dict under key 'child'
        # Actually simpler: each node is a dict mapping char -> child dict
