from typing import List

class Solution:
    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        if k == 0 or n == 0:
            return []

        # Compute diff array and a boolean array indicating if diff == 1
        diff_good = [1 if nums[i+1] - nums[i] == 1 else 0 for i in range(n-1)]
        # Prefix sum of diff_good
        pref = [0] * (len(diff_good) + 1)
        for i, val in enumerate(diff_good, 1):
            pref[i] = pref[i-1] + val

        res = []
        window_len = k - 1  # number of diffs in a window of length k
        for i in range(n - k + 1):
            # sum of diff_good from i to i+window_len-1
            sum_good = pref[i + window_len] - pref[i]
            if sum_good == window_len:
                res.append(nums[i + k - 1])  # maximum element
            else:
                res.append(-1)
        return res

from collections import deque
from typing import List

class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m, n = len(grid), len(grid[0])
        # Maximum allowed number of unsafe cells
        max_unsafe = health - 1
        if max_unsafe < 0:
            return False

        INF = 10**9
        dist = [[INF] * n for _ in range(m)]
        start_cost = grid[0][0]  # cost of stepping onto start cell
        if start_cost > max_unsafe:
            return False
        dist[0][0] = start_cost
        dq = deque()
        dq.append((0, 0))

        dirs = [(1,0),(-1,0),(0,1),(0,-1)]

        while dq:
            x, y = dq.popleft()
            cur_cost = dist[x][y]
            # Early exit if we reached target with acceptable cost
            if (x, y) == (m-1, n-1):
                if cur_cost <= max_unsafe:
                    return True
                continue

            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n:
                    add = grid[nx][ny]
                    new_cost = cur_cost + add
                    if new_cost > max_unsafe or new_cost >= dist[nx][ny]:
                        continue
                    dist[nx][ny] = new_cost
                    if add == 0:
                        dq.appendleft((nx, ny))
                    else:
                        dq.append((nx, ny))

        # After BFS, check target
        return dist[m-1][n-1] <= max_unsafe

