        vowel_set = set(vowel_to_idx.keys())
        ans = 0

        for i in range(n):
            vowel_counts = [0] * 5
            cons_count = 0
            for j in range(i, n):
                ch = word[j]
                if ch in vowel_set:
                    vowel_counts[vowel_to_idx[ch]] += 1
                else:
                    cons_count += 1

                if cons_count > k:
