import sys

def invert_case(ch: str) -> str:
    """Return the letter with inverted case."""
    if 'a' <= ch <= 'z':
        return ch.upper()
    else:
        return ch.lower()

def main() -> None:
    data = sys.stdin.read().split()
    S = data[0]
    Q = int(data[1])
    Ks = list(map(int, data[2:2 + Q]))

    n0 = len(S)
    res = []

    for K in Ks:
        len_cur = n0
        # find level that already contains position K
        while len_cur < K:
            len_cur <<= 1

        invert_flag = False
        # walk back to original string
        while len_cur > n0:
            mid = len_cur >> 1
            if K > mid:
                K -= mid
                invert_flag = not invert_flag
            len_cur = mid

        c = S[K - 1]  # 0-indexed
        if invert_flag:
            c = invert_case(c)
        res.append(c)

    print(' '.join(res))

if __name__ == "__main__":
    main()

