from array import array

def solve() -> None:
    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        return
    n = data[0]
    heights = data[1:]

    # Group positions by height
    pos_by_height = {}
    for idx, h in enumerate(heights):
        pos_by_height.setdefault(h, []).append(idx)

    max_len = 1

    for h, pos in pos_by_height.items():
        m = len(pos)
        if m <= max_len:
            continue  # cannot beat current best

        # Map position to its index in pos list
        pos_to_index = {p: i for i, p in enumerate(pos)}

        # dp[j] is an array of length j, storing lengths ending at j with previous index i
        dp = [array('H', [0] * j) for j in range(m)]

        for j in range(m):
            pj = pos[j]
            for i in range(j):
                pi = pos[i]
                diff = pj - pi
                ki = pos_to_index.get(pi - diff)
                if ki is not None and ki < i:
                    length = dp[i][ki] + 1
                else:
                    length = 2
                dp[j][i] = length
                if length > max_len:
                    max_len = length

    print(max_len)

