import sys

def can_convert_k1(S: str, T: str) -> bool:
    n, m = len(S), len(T)
    if S == T:
        return True
    if abs(n - m) > 1:
        return False
    if n == m:
        diff = 0
        for a, b in zip(S, T):
            if a != b:
                diff += 1
                if diff > 1:
                    return False
        return diff == 1
    # len difference is exactly 1
    # ensure S is the shorter one for insertion case
    if n < m:
        # need to insert one char into S to get T
        i = 0
        while i < n and S[i] == T[i]:
            i += 1
        # if all matched, insertion at end
        if i == n:
            return True
        # otherwise, check rest matches after skipping one char in T
        return S[i:] == T[i+1:]
    else:
        # n > m: need to delete one char from S
        i = 0
        while i < m and S[i] == T[i]:
            i += 1
        if i == m:
            return True
        return S[i+1:] == T[i:]

