import heapq
from typing import List

class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n, m = len(moveTime), len(moveTime[0])
        INF = 10**20
        dist = [[INF] * m for _ in range(n)]
        dist[0][0] = 0
        pq = [(0, 0, 0)]  # (current_time, i, j)
        dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        while pq:
            cur, i, j = heapq.heappop(pq)
            if cur != dist[i][j]:
                continue
            if i == n-1 and j == m-1:
                return cur
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m:
                    depart = max(cur, moveTime[ni][nj])
                    nxt = depart + 1
                    if nxt < dist[ni][nj]:
                        dist[ni][nj] = nxt
                        heapq.heappush(pq, (nxt, ni, nj))
        return dist[n-1][m-1]

