class Solution:
    def isZeroArray(self, nums: List[int], queries: List[List[int]]) -> bool:
        n = len(nums)
        diff = [0] * (n + 1)  # difference array for coverage counts

        # Build difference array from queries
        for l, r in queries:
            diff[l] += 1
            if r + 1 < n:
                diff[r + 1] -= 1

        # Prefix sum to get coverage for each index
        cover = 0
        for i in range(n):
            cover += diff[i]
            if cover < nums[i]:
                return False  # not enough queries covering this index

        return True

