from typing import List

class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        INF = 10**18
        # Build distance matrix for 26 letters
        dist = [[INF] * 26 for _ in range(26)]
        for i in range(26):
            dist[i][i] = 0
            dist[i][(i + 1) % 26] = nextCost[i]
            dist[i][(i - 1) % 26] = previousCost[i]

        # Floyd–Warshall to compute all‑pairs shortest paths
        for k in range(26):
            dk = dist[k]
            for i in range(26):
                di = dist[i]
                aik = di[k]
                if aik == INF:
                    continue
                for j in range(26):
                    # di[j] = min(di[j], di[k] + dk[j])
                    val = aik + dk[j]
                    if val < di[j]:
                        di[j] = val

        total = 0
        for ch_s, ch_t in zip(s, t):
            src = ord(ch_s) - 97
            dst = ord(ch_t) - 97
            total += dist[src][dst]
        return total

from typing import List
from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = Counter(nums)
        best = None
        for s in nums:
            o = total - 2 * s
            if o in freq:
                if o != s or freq[o] >= 2:
                    if best is None or o > best:
                        best = o
        # The problem guarantees at least one outlier exists
        return best

