from typing import List

class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float],
                  pairs2: List[List[str]], rates2: List[float]) -> float:
        # Collect all unique currencies
        currencies = set([initialCurrency])
        for a, b in pairs1 + pairs2:
            currencies.add(a)
            currencies.add(b)
        currency_to_idx = {c: i for i, c in enumerate(currencies)}
        n = len(currencies)

        # Helper to build best rate matrix for a day's pairs
        def build_matrix(pairs: List[List[str]], rates: List[float]) -> List[List[float]]:
            mat = [[0.0] * n for _ in range(n)]
            for i in range(n):
                mat[i][i] = 1.0
            for (u, v), r in zip(pairs, rates):
                ui, vi = currency_to_idx[u], currency_to_idx[v]
                if r > mat[ui][vi]:
                    mat[ui][vi] = r
                inv = 1.0 / r
                if inv > mat[vi][ui]:
                    mat[vi][ui] = inv
            # Floyd-Warshall for max product
            for k in range(n):
                mk = mat[k]
                for i in range(n):
                    mi = mat[i]
                    aik = mi[k]
                    if aik == 0.0:
                        continue
                    for j in range(n):
                        val = aik * mk[j]
                        if val > mi[j]:
                            mi[j] = val
            return mat

        mat1 = build_matrix(pairs1, rates1)
        mat2 = build_matrix(pairs2, rates2)

        init_idx = currency_to_idx[initialCurrency]
        max_amount = 1.0  # zero conversions
        for x in range(n):
            amt = mat1[init_idx][x] * mat2[x][init_idx]
            if amt > max_amount:
                max_amount = amt
        return max_amount

