class Solution:
    def answerString(self, word: str, numFriends: int) -> str:
        n = len(word)
        # Length of the longest allowed substring
        L = n - numFriends + 1
        # Find the lexicographically largest suffix
        best_start = 0
        for i in range(1, n):
            # Python string comparison is efficient
            if word[i:] > word[best_start:]:
                best_start = i
        # Return the prefix of that suffix with length at most L
        return word[best_start:best_start + L]

import math
from bisect import bisect_left
from collections import defaultdict
from typing import List

class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        # If all elements equal, answer is combinatorial
        if all(x == nums[0] for x in nums):
            # number of quadruples with gaps > 1 is C(n-3, 4)
            if n < 7:
                return 0
            return math.comb(n - 3, 4)

        # Build left pairs (p, r) with r - p > 1
        left_pairs_by_prod = defaultdict(list)
        for p in range(n):
            for r in range(p + 2, n):
                prod = nums[p] * nums[r]
                left_pairs_by_prod[prod].append((p, r))

