from bisect import bisect_left
from collections import defaultdict
from typing import List

class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        # If all elements equal, answer is combinatorial
        if all(x == nums[0] for x in nums):
            # number of quadruples with gaps > 1 is C(n-3, 4)
            if n < 7:
                return 0
            return math.comb(n - 3, 4)

        # Build left pairs (p, r) with r - p > 1
        left_pairs_by_prod = defaultdict(list)
        for p in range(n):
            for r in range(p + 2, n):
                prod = nums[p] * nums[r]
                left_pairs_by_prod[prod].append((p, r))

        # Build right pairs (q, s) with s - q > 1
        right_pairs_by_prod = defaultdict(list)
        for q in range(n):
            for s in range(q + 2, n):
                prod = nums[q] * nums[s]
                right_pairs_by_prod[prod].append((q, s))

        ans = 0

        # Process each product present in both
