from typing import List

class Solution:
    MOD = 10**9 + 7

    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])

        # dp[i][j][x] = number of ways to reach (i,j) with XOR value x
        dp = [[[0] * 16 for _ in range(n)] for _ in range(m)]
        dp[0][0][grid[0][0]] = 1

        for i in range(m):
            for j in range(n):
                cur = dp[i][j]
                if i == m - 1 and j == n - 1:
                    continue
                for x in range(16):
                    ways = cur[x]
                    if ways == 0:
                        continue
                    if i + 1 < m:
                        nx = x ^ grid[i + 1][j]
                        dp[i + 1][j][nx] = (dp[i + 1][j][nx] + ways) % self.MOD
                    if j + 1 < n:
                        ny = x ^ grid[i][j + 1]
                        dp[i][j + 1][ny] = (dp[i][j + 1][ny] + ways) % self.MOD

        return dp[m - 1][n - 1][k]

