class Solution:
    def calculateScore(self, s: str) -> int:
        # Stacks for each letter a-z (indices 0-25)
        stacks = [[] for _ in range(26)]
        score = 0

        for i, ch in enumerate(s):
            idx = ord(ch) - ord('a')
            mir = 25 - idx  # index of the mirror letter

            if stacks[mir]:
                j = stacks[mir].pop()
                score += i - j
            else:
                stacks[idx].append(i)

        return score

