import sys

def solve() -> None:
    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        return
    it = iter(data)
    N = next(it)
    dice = []
    for _ in range(N):
        K = next(it)
        faces = [next(it) for _ in range(K)]
        freq = {}
        for v in faces:
            freq[v] = freq.get(v, 0) + 1
        dice.append((K, freq))

    max_prob = 0.0
    for i in range(N):
        Ki, freq_i = dice[i]
        for j in range(i + 1, N):
            Kj, freq_j = dice[j]
            denom = Ki * Kj
            # iterate over smaller dict for efficiency
            if len(freq_i) < len(freq_j):
                small, large = freq_i, freq_j
            else:
                small, large = freq_j, freq_i
            prob = 0.0
            for v, cnt_small in small.items():
                cnt_large = large.get(v)
                if cnt_large:
                    prob += cnt_small * cnt_large
            prob /= denom
            if prob > max_prob:
                max_prob = prob

    # Print with sufficient precision
    print("{:.15f}".format(max_prob))

if __name__ == "__main__":
    solve()

