import sys

def is_colorful_bracket_sequence(s: str) -> bool:
    stack = []
    match = {')': '(', ']': '[', '>': '<'}
    for ch in s:
        if ch in "([<":
            stack.append(ch)
        else:  # closing
            if not stack or stack[-1] != match[ch]:
                return False
            stack.pop()
    return not stack

def main() -> None:
    s = sys.stdin.readline().strip()
    print("Yes" if is_colorful_bracket_sequence(s) else "No")

if __name__ == "__main__":
    main()

