def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    cards = list(map(int, data))
    freq = Counter(cards)
    # Find ranks with count >=3 and >=2
    has_three = False
    has_two = False
    for r, cnt in freq.items():
        if cnt >= 3:
            has_three = True
        if cnt >= 2:
            has_two = True
    # Need distinct ranks: at least one rank with >=3 and another distinct rank with >=2
    # If the same rank satisfies both, we still need another rank with >=2
    # So we check all combinations explicitly
    ranks = list(freq.keys())
    ok = False
    for x in ranks:
        if freq[x] < 3:
            continue
        for y in ranks:
            if x == y:
                continue
            if freq[y] >= 2:
                ok = True
                break
        if ok:
            break
    print("Yes" if ok else "No")

if __name__ == "__main__":
