def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        N = int(next(it))
        M = int(next(it))
    except StopIteration:
        return
    A = [int(next(it)) for _ in range(N)]
    B = [int(next(it)) for _ in range(M)]

    # Compute earliest positions L
    L = [0] * M
    p = 0  # index in B
    for i, a in enumerate(A):
        if p < M and a == B[p]:
            L[p] = i + 1  # use 1-indexed for clarity
            p += 1
            if p == M:
                break
    if p < M:
        print("No")
        return

    # Compute latest positions R
    R = [0] * M
    q = M - 1
    for i in range(N - 1, -1, -1):
        a = A[i]
        if q >= 0 and a == B[q]:
            R[q] = i + 1
            q -= 1
            if q < 0:
                break
    if q >= 0:
        print("No")
        return

    # Check if any position can differ
    for j in range(M):
        if L[j] < R[j]:
            print("Yes")
            return
    print("No")

