from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        INF = -10 ** 15
        # dp[i][j][k]: max profit at cell (i,j) after using k neutralizations
        dp = [[[INF] * 3 for _ in range(n)] for _ in range(m)]

        # initialize start cell
        start_val = coins[0][0]
        dp[0][0][0] = start_val
        if start_val < 0:          # we can neutralize the first robber
            dp[0][0][1] = 0

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                # reset dp[i][j] (already INF, but keep for clarity)
                # process neighbors
                for di, dj in ((i - 1, j), (i, j - 1)):
                    if di < 0 or dj < 0:
                        continue
                    for used in range(3):
                        prev = dp[di][dj][used]
                        if prev == INF:
                            continue
                        cur_val = coins[i][j]
                        if cur_val >= 0:
                            # normal cell, no choice
                            if prev + cur_val > dp[i][j][used]:
                                dp[i][j][used] = prev + cur_val
                        else:
                            # keep the negative value
                            if prev + cur_val > dp[i][j][used]:
                                dp[i][j][used] = prev + cur_val
                            # neutralize this robber if we have capacity
                            if used < 2:
                                if prev > dp[i][j][used + 1]:
                                    dp[i][j][used + 1] = prev

        return max(dp[m - 1][n - 1])

