class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**18
        m = n // 2  # number of pairs

        # dp_prev[cl][cr] = min cost up to previous pair with colors cl (left) and cr (right)
        dp_prev = [[INF] * 3 for _ in range(3)]

        # Base case for k = 0 (pair (0, n-1))
        for cl in range(3):
            for cr in range(3):
                if cl == cr:  # mirror constraint
                    continue
                dp_prev[cl][cr] = cost[0][cl] + cost[n - 1][cr]

        # Process remaining pairs
        for k in range(1, m):
            dp_cur = [[INF] * 3 for _ in range(3)]
            left_idx = k
            right_idx = n - 1 - k
            for cl in range(3):
                for cr in range(3):
                    if cl == cr:  # mirror constraint
                        continue
                    best = INF
                    # try all previous colors
                    for pl in range(3):
                        if pl == cl:  # adjacent on left chain
                            continue
                        for pr in range(3):
                            if pr == cr:  # adjacent on right chain
                                continue
                            val = dp_prev[pl][pr]
                            if val < INF:
                                val += cost[left_idx][cl] + cost[right_idx][cr]
                                if val < best:
                                    best = val
                    dp_cur[cl][cr] = best
            dp_prev = dp_cur

        # Answer is minimal over all color assignments of the last pair
        ans = INF
        for cl in range(3):
            for cr in range(3):
                if dp_prev[cl][cr] < ans:
                    ans = dp_prev[cl][cr]
        return ans

