from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # Count of existing k's
        count_k = nums.count(k)
        # If all elements are k, answer is n
        if count_k == n:
            return n

        max_gain = 0  # maximum (count_v - count_k) over all subarrays and v != k

        # Iterate over all possible values of v (1..50) except k
        for v in range(1, 51):
            if v == k:
                continue
            # Kadane's algorithm on transformed array
            cur = 0
            best = 0
            for num in nums:
                if num == v:
                    val = 1
                elif num == k:
                    val = -1
                else:
                    val = 0
                cur = max(val, cur + val)
                best = max(best, cur)
            if best > max_gain:
                max_gain = best

        # Final answer: existing k's + best gain
        return count_k + max_gain

