from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        if not groups or not elements:
            return [-1] * len(groups)

        max_val = max(max(groups), max(elements))
        INF = 10**9

        # Step 1: For each element value, keep the smallest index
        min_index_for_value = [INF] * (max_val + 1)
        for idx, val in enumerate(elements):
            if idx < min_index_for_value[val]:
                min_index_for_value[val] = idx

        # Step 2: For each number up to max_val, compute the minimal index among
        # elements that divide it (by iterating over multiples)
        best_idx_for_number = [INF] * (max_val + 1)
        for val in range(1, max_val + 1):
            idx = min_index_for_value[val]
            if idx == INF:
                continue
            # Update all multiples of val
            for multiple in range(val, max_val + 1, val):
                if idx < best_idx_for_number[multiple]:
                    best_idx_for_number[multiple] = idx

        # Step 3: Build answer for each group
        result = []
        for g in groups:
            idx = best_idx_for_number[g]
            result.append(idx if idx != INF else -1)

        return result

