class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        if k == 0:
            return True

        # compute first and last occurrence for each letter
        first = [-1] * 26
        last = [-1] * 26
        for i, ch in enumerate(s):
            idx = ord(ch) - 97
            if first[idx] == -1:
                first[idx] = i
            last[idx] = i

        intervals = []

        # For each position that is the first occurrence of its letter,
        # find the minimal closed interval starting there.
        for l in range(n):
            idx = ord(s[l]) - 97
            if first[idx] != l:
                continue  # cannot start a closed substring here
            r = l
            i = l
            while i < n:
                r = max(r, last[ord(s[i]) - 97])
                if i == r:
                    # closed interval [l, r]
                    # skip if it is the entire string
                    if not (l == 0 and r == n - 1):
                        intervals.append((l, r))
                    break
                i += 1

        # Now choose maximum number of disjoint intervals
        intervals.sort(key=lambda x: x[1])  # sort by end
        count = 0
        last_end = -1
        for l, r in intervals:
            if l > last_end:
                count += 1
                last_end = r
                if count >= k:
                    return True

        return False

import sys
import threading

def solve():
    import sys

    data = sys.stdin.read().strip().split()
    if not data:
        return
    s = data[0].strip()
    k = int(data[1])
    n = len(s)
    # Precompute minimal cost to pair i and j: distance between letters
    def dist(a, b):
        d = abs(ord(a) - ord(b))
        return min(d, 26 - d)
    pair_cost = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            pair_cost[i][j] = dist(s[i], s[j])

    # dp[i][j][c] = max length achievable in s[i..j] with total cost <= c
    # We'll store as list of lists of lists
    dp = [[ [0]*(k+1) for _ in range(n) ] for _ in range(n)]

    # Base cases: single character
    for i in range(n):
        for c in range(k+1):
            dp[i][i][c] = 1

    # Process intervals of increasing length
    for length in range(2, n+1):
        for i in range(n - length + 1):
            j = i + length - 1
            cost_pair = pair_cost[i][j]
            for c in range(k+1):
                best = 0
                # skip i
                if i+1 <= j:
                    best = max(best, dp[i+1][j][c])
                # skip j
                if i <= j-1:
                    best = max(best, dp[i][j-1][c])
                # pair i and j
                if c >= cost_pair:
                    if i+1 <= j-1:
                        pair_len = dp[i+1][j-1][c - cost_pair] + 2
                    else:
                        pair_len = 2
                    best = max(best, pair_len)
                dp[i][j][c] = best

    # Result is best length for cost <= k in whole string
    print(dp[0][n-1][k])

def main():
    solve()

threading.Thread(target=main).start()

