from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        # Prefix sums
        S = [0] * (n + 1)
        for i in range(n):
            S[i + 1] = S[i] + nums[i]

        NEG_INF = -10**18
        # DP[i][j] = max sum using j subarrays in first i elements
        dp = [[NEG_INF] * (k + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            dp[i][0] = 0

        # best[j] = max over pos <= current_i - m of dp[pos][j-1] - S[pos]
        best = [NEG_INF] * (k + 1)

        for i in range(1, n + 1):
            # For each j, update best[j] with position i-m
            pos = i - m
            if pos >= 0:
                for j in range(1, k + 1):
                    val = dp[pos][j - 1] - S[pos]
                    if val > best[j]:
                        best[j] = val
            # Compute dp[i][j]
            for j in range(1, k + 1):
                # Option 1: don't take a subarray ending at i-1
                opt1 = dp[i - 1][j]
                # Option 2: take a subarray ending at i-1
                opt2 = NEG_INF
                if best[j] != NEG_INF:
                    opt2 = best[j] + S[i]
                dp[i][j] = opt1 if opt1 > opt2 else opt2

        return dp[n][k]

from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        seg = [0] * (4 * n)

        def build(node: int, l: int, r: int) -> None:
            if l == r:
                seg[node] = baskets[l]
            else:
                m = (l + r) // 2
                build(node * 2, l, m)
                build(node * 2 + 1, m + 1, r)
                seg[node] = max(seg[node * 2], seg[node * 2 + 1])

        def query(node: int, l: int, r: int, x: int) -> int:
            """Return the leftmost index in [l, r] with capacity >= x, or -1."""
            if seg[node] < x:
                return -1
            if l == r:
                return l
            m = (l + r) // 2
            res = query(node * 2, l, m, x)
            if res != -1:
                return res
            return query(node * 2 + 1, m + 1, r, x)

        def update(node: int, l: int, r: int, idx: int) -> None:
            """Mark basket at idx as used by setting its capacity to -1."""
            if l == r:
                seg[node] = -1
            else:
                m = (l + r) // 2
                if idx <= m:
                    update(node * 2, l, m, idx)
                else:
                    update(node * 2 + 1, m + 1, r, idx)
                seg[node] = max(seg[node * 2], seg[node * 2 + 1])

        build(1, 0, n - 1)

        unplaced = 0
        for f in fruits:
            pos = query(1, 0, n - 1, f)
            if pos == -1:
                unplaced += 1
            else:
                update(1, 0, n - 1, pos)

        return unplaced

