from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # dp[i] is a bitset (int) where bit s is set if sum s achievable for index i
        dp = [1] * n  # only sum 0 is reachable initially

        for k, (l, r, val) in enumerate(queries, 1):
            # Update dp for indices in [l, r]
            shift = val
            mask = (1 << (max(nums) + 1)) - 1  # limit bits to max needed
            for i in range(l, r + 1):
                dp[i] |= (dp[i] << shift) & mask
            # Check if all indices can reach their required value
            all_zero = True
            for i in range(n):
                if (dp[i] >> nums[i]) & 1 == 0:
                    all_zero = False
                    break
            if all_zero:
                return k
        return -1

