from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Convert each row to a set of distinct integers
        sets = [set(row) for row in properties]

        # Union-Find data structure
        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            pa, pb = find(a), find(b)
            if pa != pb:
                parent[pa] = pb

        # Build edges based on intersection size
        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        # Count distinct components
        roots = {find(i) for i in range(n)}
        return len(roots)

# Example usage:
if __name__ == "__main__":
    sol = Solution()
    print(sol.numberOfComponents([[1,2],[1,1],[3,4],[4,5],[5,6],[7,7]], 1))  # Output: 3
    print(sol.numberOfComponents([[1,2,3],[2,3,4],[4,3,5]], 2))            # Output: 1
    print(sol.numberOfComponents([[1,1],[1,1]], 2))                        # Output: 2

