from itertools import combinations

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        # dp maps a tuple of pending indices (sorted) to minimal cost so far
        dp = {(): 0}
        INF = 10**18

        for i in range(n):
            new_dp = {}
            for pending, cost in dp.items():
                # pending indices are from previous steps
                S = list(pending) + [i]  # current queue before removal
                if len(S) < 3:
                    # cannot remove two yet, just add the new element
                    new_pending = tuple(sorted(S))
                    if new_pending not in new_dp or cost < new_dp[new_pending]:
                        new_dp[new_pending] = cost
                else:
                    # len(S) == 3, must remove two
                    for a, b in combinations(S, 2):
                        remaining = [x for x in S if x != a and x != b]
                        new_pending = tuple(sorted(remaining))
                        new_cost = cost + max(nums[a], nums[b])
                        if new_pending not in new_dp or new_cost < new_dp[new_pending]:
                            new_dp[new_pending] = new_cost
            dp = new_dp

        # After processing all elements, remove the remaining pending elements in one operation
        best = INF
